1	use std::{
2	    collections::BinaryHeap,
3	    sync::Arc,
4	    thread,
5	    time::{Duration, Instant},
6	};
7	
8	use parking_lot::{Condvar, Mutex};
9	
10	use crate::{
11	    PlatformDispatcher, Priority, RunnableVariant, profiler,
12	    queue::{PriorityQueueReceiver, PriorityQueueSender},
13	};
14	
15	const MIN_THREADS: usize = 2;
16	
17	/// A multithreaded [`PlatformDispatcher`] for tests and benchmarks.
18	///
19	/// Background tasks run in parallel on a pool of worker threads and timers fire
20	/// in real time on a dedicated timer thread, mirroring the production
21	/// dispatchers (see `LinuxDispatcher`). Main-thread tasks are queued until the
22	/// creating thread drains them via [`Self::run_until_idle`], since there is no
23	/// platform run loop pumping them.
24	///
25	/// Unlike [`TestDispatcher`](crate::TestDispatcher), which runs everything on a
26	/// single thread with a virtual clock, work dispatched through this dispatcher
27	/// executes with production concurrency.
28	pub struct ThreadedDispatcher {
29	    background_sender: PriorityQueueSender<RunnableVariant>,
30	    main_sender: PriorityQueueSender<RunnableVariant>,
31	    main_receiver: Mutex<PriorityQueueReceiver<RunnableVariant>>,
32	    timers: Arc<TimerQueue>,
33	    idle: Arc<IdleTracker>,
34	    main_thread_id: thread::ThreadId,
35	}
36	
37	/// Tracks how many background and timer runnables are queued or running so
38	/// [`ThreadedDispatcher::run_until_idle`] knows when to stop waiting.
39	#[derive(Default)]
40	struct IdleTracker {
41	    inflight: Mutex<usize>,
42	    condvar: Condvar,
43	}
44	
45	impl IdleTracker {
46	    fn increment(&self) {
47	        *self.inflight.lock() += 1;
48	    }
49	
50	    fn decrement(&self) {
51	        let mut inflight = self.inflight.lock();
52	        *inflight -= 1;
53	        if *inflight == 0 {
54	            self.condvar.notify_all();
55	        }
56	    }
57	
58	    /// Returns a guard that decrements the in-flight count when dropped, so
59	    /// the count stays correct even if the runnable being executed panics.
60	    fn decrement_on_drop(&self) -> impl Drop + '_ {
61	        gpui_util::defer(|| self.decrement())
62	    }
63	
64	    /// Notifies waiters while holding the in-flight lock. `run_until_idle`
65	    /// re-checks its wake conditions under this lock before waiting, so the
66	    /// notification can't slip between its check and its wait and be lost.
67	    fn notify_under_lock(&self) {
68	        let _inflight = self.inflight.lock();
69	        self.condvar.notify_all();
70	    }
71	}
72	
73	struct TimerQueue {
74	    state: Mutex<TimerQueueState>,
75	    condvar: Condvar,
76	}
77	
78	struct TimerQueueState {
79	    heap: BinaryHeap<TimerEntry>,
80	    next_seq: u64,
81	}
82	
83	struct TimerEntry {
84	    due: Instant,
85	    seq: u64,
86	    runnable: RunnableVariant,
87	}
88	
89	impl PartialEq for TimerEntry {
90	    fn eq(&self, other: &Self) -> bool {
91	        self.due == other.due && self.seq == other.seq
92	    }
93	}
94	
95	impl Eq for TimerEntry {}
96	
97	impl PartialOrd for TimerEntry {
98	    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
99	        Some(self.cmp(other))
100	    }
101	}
102	
103	impl Ord for TimerEntry {
104	    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
105	        // Reversed so that the entry with the earliest due time (breaking ties
106	        // by insertion order) is at the top of the max-heap.
107	        other
108	            .due
109	            .cmp(&self.due)
110	            .then_with(|| other.seq.cmp(&self.seq))
111	    }
112	}
113	
114	impl Default for ThreadedDispatcher {
115	    fn default() -> Self {
116	        Self::new()
117	    }
118	}
119	
120	impl ThreadedDispatcher {
121	    /// Creates a dispatcher whose main thread is the calling thread.
122	    ///
123	    /// Worker and timer threads live for the lifetime of the process; the
124	    /// dispatcher is expected to be created once and reused.
125	    pub fn new() -> Self {
126	        let (background_sender, background_receiver) = PriorityQueueReceiver::new();
127	        let (main_sender, main_receiver) = PriorityQueueReceiver::new();
128	        let idle = Arc::new(IdleTracker::default());
129	
130	        let thread_count =
131	            thread::available_parallelism().map_or(MIN_THREADS, |i| i.get().max(MIN_THREADS));
132	        for i in 0..thread_count {
133	            let mut receiver: PriorityQueueReceiver<RunnableVariant> = background_receiver.clone();
134	            let idle = idle.clone();
135	            thread::Builder::new()
136	                .name(format!("ThreadedDispatcherWorker-{i}"))
137	                .spawn(move || {
138	                    while let Ok(runnable) = receiver.pop() {
139	                        let _decrement = idle.decrement_on_drop();
140	                        let location = runnable.metadata().location;
141	                        let spawned = runnable.metadata().spawned;
142	                        profiler::update_running_task(spawned, location);
143	                        runnable.run();
144	                        profiler::save_task_timing();
145	                    }
146	                })
147	                .expect("failed to spawn threaded dispatcher worker");
148	        }
149	        drop(background_receiver);
150	
151	        let timers = Arc::new(TimerQueue {
152	            state: Mutex::new(TimerQueueState {
153	                heap: BinaryHeap::new(),
154	                next_seq: 0,
155	            }),
156	            condvar: Condvar::new(),
157	        });
158	        {
159	            let timers = timers.clone();
160	            let idle = idle.clone();
161	            thread::Builder::new()
162	                .name("ThreadedDispatcherTimer".to_owned())
163	                .spawn(move || {
164	                    let mut state = timers.state.lock();
165	                    loop {
166	                        let Some(entry) = state.heap.peek() else {
167	                            timers.condvar.wait(&mut state);
168	                            continue;
169	                        };
170	                        let due = entry.due;
171	                        if due > Instant::now() {
172	                            timers.condvar.wait_until(&mut state, due);
173	                            continue;
174	                        }
175	                        let Some(entry) = state.heap.pop() else {
176	                            continue;
177	                        };
178	                        // Count the firing timer as in-flight before releasing
179	                        // the lock so it can spawn follow-up work that
180	                        // `run_until_idle` will wait for. Lock order is always
181	                        // timer state, then in-flight count; `run_until_idle`
182	                        // never takes them in the opposite order.
183	                        idle.increment();
184	                        drop(state);
185	
186	                        {
187	                            let _decrement = idle.decrement_on_drop();
188	                            let location = entry.runnable.metadata().location;
189	                            let spawned = entry.runnable.metadata().spawned;
190	                            profiler::update_running_task(spawned, location);
191	                            entry.runnable.run();
192	                            profiler::save_task_timing();
193	                        }
194	
195	                        state = timers.state.lock();
196	                    }
197	                })
198	                .expect("failed to spawn threaded dispatcher timer");
199	        }
200	
201	        Self {
202	            background_sender,
203	            main_sender,
204	            main_receiver: Mutex::new(main_receiver),
205	            timers,
206	            idle,
207	            main_thread_id: thread::current().id(),
208	        }
209	    }
210	
211	    /// Runs queued main thread tasks and waits until no background or timer
212	    /// work is queued, running, or already due.
213	    ///
214	    /// Timers that haven't reached their due time yet are *not* waited for:
215	    /// the dispatcher runs in real time and cannot skip ahead like the
216	    /// `TestDispatcher`'s virtual clock, so waiting on a future timer would
217	    /// block for its full real duration. Tasks sleeping on such timers are
218	    /// considered idle. Must be called on the thread that created this
219	    /// dispatcher.
220	    pub fn run_until_idle(&self) {
221	        assert!(
222	            self.is_main_thread(),
223	            "run_until_idle must be called on the threaded dispatcher's main thread"
224	        );
225	        loop {
226	            if self.drain_main_queue() {
227	                continue;
228	            }
229	
230	            // Checked before taking the in-flight lock; the timer thread
231	            // locks them in the opposite order, so nesting would deadlock.
232	            if self.has_due_timer() {
233	                // Poll briefly: a firing timer leaves the heap just before it
234	                // registers as in-flight.
235	                let mut inflight = self.idle.inflight.lock();
236	                self.idle
237	                    .condvar
238	                    .wait_for(&mut inflight, Duration::from_millis(1));
239	                continue;
240	            }
241	
242	            let mut inflight = self.idle.inflight.lock();
243	            // Re-checked under the lock that `dispatch_on_main_thread`
244	            // notifies under, so the notification can't be lost.
245	            if self.main_queue_has_work() {
246	                continue;
247	            }
248	            if *inflight == 0 {
249	                // Main-thread sends happen before in-flight decrements, and
250	                // decrements happen under this lock, so the check above
251	                // observed all completed work.
252	                return;
253	            }
254	            // Woken when main-thread work arrives or the in-flight count
255	            // reaches zero; both notify under this lock.
256	            self.idle.condvar.wait(&mut inflight);
257	        }
258	    }
259	
260	    /// Drives main-thread work until `ready` returns a value.
261	    ///
262	    /// Unlike [`Self::run_until_idle`], this waits across temporary quiescence.
263	    /// This is required when completion can arrive from an external worker that
264	    /// is not represented in the dispatcher's in-flight count.
265	    ///
266	    /// Readiness is checked before every main-thread runnable, so this returns
267	    /// as soon as `ready` observes completion rather than after the queue
268	    /// drains — deferred work that re-queues itself (idle sweeps, pollers)
269	    /// must not extend a benchmark's measured interval past the completion it
270	    /// awaits.
271	    #[cfg(any(test, feature = "bench"))]
272	    pub(crate) fn run_until<R>(&self, mut ready: impl FnMut() -> Option<R>) -> R {
273	        assert!(
274	            self.is_main_thread(),
275	            "run_until must be called on the threaded dispatcher's main thread"
276	        );
277	        loop {
278	            if let Some(result) = ready() {
279	                return result;
280	            }
281	            if self.run_one_main_task() {
282	                continue;
283	            }
284	
285	            let mut inflight = self.idle.inflight.lock();
286	            if self.main_queue_has_work() {
287	                continue;
288	            }
289	            self.idle.condvar.wait(&mut inflight);
290	        }
291	    }
292	
293	    /// Runs at most one queued main-thread task, returning whether one ran.
294	    ///
295	    /// [`Self::run_until`] steps tasks one at a time so it can observe
296	    /// readiness between them: a task that perpetually re-queues itself (like
297	    /// an idle-time sweep) would otherwise keep [`Self::drain_main_queue`]
298	    /// looping past the completion the caller is waiting for.
299	    #[cfg(any(test, feature = "bench"))]
300	    fn run_one_main_task(&self) -> bool {
301	        let runnable = self.main_receiver.lock().try_pop();
302	        match runnable {
303	            Ok(Some(runnable)) => {
304	                let location = runnable.metadata().location;
305	                let spawned = runnable.metadata().spawned;
306	                profiler::update_running_task(spawned, location);
307	                runnable.run();
308	                profiler::save_task_timing();
309	                true
310	            }
311	            Ok(None) | Err(_) => false,
312	        }
313	    }
314	
315	    /// Runs the main-thread tasks that were queued when the call began,
316	    /// returning whether any ran. Tasks dispatched while running (e.g. a task
317	    /// re-queuing itself after yielding) are left for the next call, as on
318	    /// the platform run loops.
319	    pub fn run_ready_main_tasks(&self) -> bool {
320	        assert!(
321	            self.is_main_thread(),
322	            "run_ready_main_tasks must be called on the threaded dispatcher's main thread"
323	        );
324	        let pending = self.main_receiver.lock().len();
325	        let mut ran_any = false;
326	        for _ in 0..pending {
327	            let runnable = self.main_receiver.lock().try_pop();
328	            match runnable {
329	                Ok(Some(runnable)) => {
330	                    let location = runnable.metadata().location;
331	                    let spawned = runnable.metadata().spawned;
332	                    profiler::update_running_task(spawned, location);
333	                    runnable.run();
334	                    profiler::save_task_timing();
335	                    ran_any = true;
336	                }
337	                Ok(None) | Err(_) => break,
338	            }
339	        }
340	        ran_any
341	    }
342	
343	    /// Cancels all pending timers so timers armed by one workload can't fire
344	    /// during a later workload sharing this process-lifetime dispatcher.
345	    ///
346	    /// Dropping a timer runnable drops its completion sender, waking the task
347	    /// awaiting the timer. Call [`Self::run_until_idle`] after this method to
348	    /// drain any work that cancellation unblocks.
349	    pub fn cancel_pending_timers(&self) -> usize {
350	        let timers = {
351	            let mut state = self.timers.state.lock();
352	            let timers: Vec<_> = state.heap.drain().collect();
353	            self.timers.condvar.notify_all();
354	            timers
355	        };
356	        let canceled = timers.len();
357	        drop(timers);
358	        canceled
359	    }
360	
361	    /// Describes the dispatcher's idle-tracking state, for diagnosing
362	    /// workloads that fail to reach quiescence.
363	    pub fn debug_state(&self) -> String {
364	        let inflight = *self.idle.inflight.lock();
365	        let timers = self.timers.state.lock().heap.len();
366	        let main_queue_has_work = self.main_queue_has_work();
367	        format!(
368	            "ThreadedDispatcher {{ inflight: {inflight}, pending_timers: {timers}, \
369	             main_queue_has_work: {main_queue_has_work} }}"
370	        )
371	    }
372	
373	    /// Whether no main-thread work is queued, no background or timer
374	    /// runnables are queued or running, and no armed timer is due. Timers
375	    /// that aren't due yet are ignored, as in [`Self::run_until_idle`].
376	    #[cfg(any(test, feature = "bench"))]
377	    pub(crate) fn is_idle(&self) -> bool {
378	        !self.main_queue_has_work() && !self.has_due_timer() && *self.idle.inflight.lock() == 0
379	    }
380	
381	    fn has_due_timer(&self) -> bool {
382	        let state = self.timers.state.lock();
383	        state
384	            .heap
385	            .peek()
386	            .is_some_and(|entry| entry.due <= Instant::now())
387	    }
388	
389	    fn main_queue_has_work(&self) -> bool {
390	        !self.main_receiver.lock().is_empty()
391	    }
392	
393	    fn drain_main_queue(&self) -> bool {
394	        let mut ran_any = false;
395	        loop {
396	            // Lock only around the pop so runnables can re-entrantly dispatch
397	            // more main-thread work through the sender while they run.
398	            let runnable = self.main_receiver.lock().try_pop();
399	            match runnable {
400	                Ok(Some(runnable)) => {
401	                    let location = runnable.metadata().location;
402	                    let spawned = runnable.metadata().spawned;
403	                    profiler::update_running_task(spawned, location);
404	                    runnable.run();
405	                    profiler::save_task_timing();
406	                    ran_any = true;
407	                }
408	                Ok(None) | Err(_) => return ran_any,
409	            }
410	        }
411	    }
412	}
413	
414	impl PlatformDispatcher for ThreadedDispatcher {
415	    fn is_main_thread(&self) -> bool {
416	        thread::current().id() == self.main_thread_id
417	    }
418	
419	    fn dispatch(&self, runnable: RunnableVariant, priority: Priority) {
420	        self.idle.increment();
421	        self.background_sender
422	            .send(priority, runnable)
423	            .unwrap_or_else(|_| panic!("threaded dispatcher workers are no longer running"));
424	    }
425	
426	    fn dispatch_on_main_thread(&self, runnable: RunnableVariant, priority: Priority) {
427	        if let Err(error) = self.main_sender.send(priority, runnable) {
428	            // The main receiver lives as long as this dispatcher, so a failed
429	            // send means we're mid-teardown. The runnable may wrap a !Send
430	            // future, so forget it rather than dropping it on this thread
431	            // (mirrors LinuxDispatcher).
432	            std::mem::forget(error);
433	            return;
434	        }
435	        // Wake `run_until_idle` if it's waiting for main-thread work.
436	        self.idle.notify_under_lock();
437	    }
438	
439	    fn dispatch_after(&self, duration: Duration, runnable: RunnableVariant) {
440	        let mut state = self.timers.state.lock();
441	        let seq = state.next_seq;
442	        state.next_seq += 1;
443	        state.heap.push(TimerEntry {
444	            due: Instant::now() + duration,
445	            seq,
446	            runnable,
447	        });
448	        self.timers.condvar.notify_one();
449	    }
450	
451	    fn spawn_realtime(&self, f: Box<dyn FnOnce() + Send>) {
452	        // This dispatcher does not need realtime scheduling priority; a plain
453	        // thread keeps it portable.
454	        thread::Builder::new()
455	            .name("ThreadedDispatcherRealtime".to_owned())
456	            .spawn(f)
457	            .expect("failed to spawn threaded dispatcher realtime thread");
458	    }
459	
460	    fn as_threaded(&self) -> Option<&ThreadedDispatcher> {
461	        Some(self)
462	    }
463	}
