90	        let http_client = http_client::FakeHttpClient::with_404_response();
91	        let app = App::new_app(platform, asset_source, http_client);
92	        app.borrow_mut().mode = GpuiMode::test();
93	
94	        Self {
95	            app,
96	            background_executor,
97	            foreground_executor,
98	            dispatcher,
99	            text_system,
